    /// <summary>
    /// Translates an English Steam store tag name to Spanish visually.
    /// </summary>
    public static string Translate(string? tagName, bool isSpanish = true)
    {
        if (string.IsNullOrWhiteSpace(tagName)) return string.Empty;
        if (!isSpanish) return tagName;
        return EnglishToSpanish.TryGetValue(tagName, out var translated) ? translated : tagName;
    }

    /// <summary>
    /// Tries to get the Spanish translation for an English tag name.
    /// </summary>
    public static bool TryGetSpanish(string? englishName, out string spanishName)
    {
        if (!string.IsNullOrWhiteSpace(englishName) && EnglishToSpanish.TryGetValue(englishName, out var trans))
        {
            spanishName = trans;
            return true;
        }
        spanishName = englishName ?? string.Empty;
        return false;
    }
